H("ac1c0582-d187-4bc8-95c3-8ef2d4c79a11",
  "केंद्र और राज्यों के बीच विधायी संबंधों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:",
  "कोई भी कथन सही नहीं है। अवशिष्ट शक्तियाँ अनुच्छेद 248 के तहत संसद के पास हैं (कनाडा जैसी व्यवस्था)। अनुच्छेद 249 के तहत प्रस्ताव एक वर्ष तक लागू रहता है (जिसे फिर बढ़ाया जा सकता है), और उसके तहत बना कानून प्रस्ताव समाप्त होने के छह महीने बाद प्रभावहीन हो जाता है। "
  "अनुच्छेद 253 के तहत संसद अंतरराष्ट्रीय संधियों, समझौतों और अभिसमयों को लागू करने के लिए, राज्य सूची के विषयों सहित, किसी भी विषय पर राज्यों की सहमति के बिना कानून बना सकती है।",
  st=["विधि-निर्माण की अवशिष्ट शक्तियाँ राज्य विधानमंडलों में निहित हैं।",
      "अनुच्छेद 249 के तहत राज्य सूची के किसी विषय पर संसद द्वारा बनाया गया कानून राज्यसभा के प्रस्ताव के समाप्त होने के बाद भी अनिश्चित काल तक लागू रहता है।",
      "संसद किसी अंतरराष्ट्रीय संधि को लागू करने के लिए राज्य सूची के किसी विषय पर केवल संबंधित राज्यों की सहमति से ही कानून बना सकती है।"])

H("354447b2-7ead-48da-82eb-4ff6aaaf2b71",
  "केंद्र-राज्य संबंधों पर निम्नलिखित समितियों में से कौन-सी केंद्र सरकार ने नहीं, बल्कि एक राज्य सरकार ने नियुक्त की थी?",
  "राजमन्नार समिति 1969 में तमिलनाडु सरकार ने केंद्र-राज्य संबंधों की जाँच के लिए नियुक्त की थी, और इसने राज्यों को अधिक स्वायत्तता की सिफ़ारिश की। "
  "सरकारिया आयोग (1983), पुंछी आयोग (2007) और संविधान के कामकाज की समीक्षा के लिए राष्ट्रीय आयोग (वेंकटचलैया, 2000), सभी केंद्र सरकार ने नियुक्त किए थे।",
  o={"a": "सरकारिया आयोग", "b": "पुंछी आयोग", "c": "राजमन्नार समिति", "d": "संविधान के कामकाज की समीक्षा के लिए राष्ट्रीय आयोग"})

H("8d6fce2b-1b51-4b07-84c2-073042ba89d4",
  "निम्नलिखित कथनों पर विचार कीजिए:",
  "कथन-I गलत है: 'संघ-राज्य' (federation) शब्द संविधान में कहीं नहीं आता। कथन-II सही है: अनुच्छेद 1 भारत, अर्थात् भारत (Bharat), को 'राज्यों का संघ' (Union of States) कहता है। "
  "डॉ. बी.आर. आंबेडकर ने समझाया था कि यह पद दर्शाता है कि यह संघ राज्यों के बीच किसी समझौते का परिणाम नहीं है, और किसी राज्य को इससे अलग होने का अधिकार नहीं है।",
  a="संविधान के अनुच्छेद 1 में भारत का वर्णन करने के लिए 'संघ-राज्य' (federation) शब्द का प्रयोग किया गया है।",
  r="अनुच्छेद 1 भारत को 'राज्यों का संघ' (Union of States) कहता है।")

H("46f7e342-7b01-418d-92f8-0bb15a962f71",
  "संविधान के अनुच्छेद 268 के तहत निम्नलिखित में से कौन-सा कर केंद्र द्वारा लगाया जाता है, पर राज्य उसे वसूलते और अपने पास रखते हैं?",
  "अनुच्छेद 268 उन शुल्कों से संबंधित है जो केंद्र लगाता है पर राज्य वसूलते और अपने पास रखते हैं: संघ सूची में उल्लिखित विनिमय-पत्रों, चेकों, वचन-पत्रों और ऐसे ही अन्य लिखतों पर स्टांप शुल्क (101वें संशोधन ने इस अनुच्छेद से औषधीय और प्रसाधन सामग्री पर उत्पाद शुल्क हटा दिया)। "
  "निगम कर और सीमा शुल्क केंद्र लगाता और वसूलता है, और कृषि आय पर कर राज्य का कर है।")

H("aa4fad02-9901-4db1-8c9f-59cddd6a31e6",
  "केंद्र और राज्यों के बीच प्रशासनिक संबंधों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:",
  "केवल कथन 1 सही है: अनुच्छेद 256 राज्यों को अपनी कार्यपालिका शक्ति का प्रयोग इस तरह करने के लिए बाध्य करता है कि केंद्रीय कानूनों का पालन हो, और केंद्र इसके लिए निर्देश दे सकता है। "
  "कथन 2 गलत है: अनुच्छेद 258(1) के तहत राष्ट्रपति केंद्र के कार्य किसी राज्य सरकार को केवल उस सरकार की सहमति से सौंप सकते हैं; बिना सहमति के ऐसा केवल अनुच्छेद 258(2) के तहत संसद के कानून से हो सकता है।",
  st=["अनुच्छेद 256 के अनुसार हर राज्य की कार्यपालिका शक्ति का प्रयोग इस तरह होना चाहिए कि संसद द्वारा बनाए गए कानूनों का पालन सुनिश्चित हो।",
      "अनुच्छेद 258 के तहत राष्ट्रपति किसी राज्य सरकार की सहमति के बिना उसे ऐसे किसी भी विषय से संबंधित कार्य सौंप सकते हैं जिस पर संघ की कार्यपालिका शक्ति का विस्तार है।"])

H("04dd0680-b52c-444a-a9a6-80e0acbbd4f9",
  "भारत के संविधान की छठी अनुसूची के संबंध में निम्नलिखित कथनों पर विचार कीजिए:",
  "कथन 1, 2 और 4 छठी अनुसूची के अनुच्छेद (पैराग्राफ़) 1, 2 और 4 के अनुसार सही हैं। "
  "कथन 3 गलत है: संसद या राज्य विधानमंडल के अधिनियम स्वायत्त ज़िलों पर अपने-आप लागू नहीं होते; राज्यपाल (या कुछ राज्यों के लिए राष्ट्रपति) निर्देश दे सकते हैं कि वे लागू नहीं होंगे, या संशोधनों और अपवादों के साथ लागू होंगे (पैराग्राफ़ 12 और संबंधित प्रावधान)।",
  st=["हर स्वायत्त ज़िले में अधिकतम तीस सदस्यों की एक ज़िला परिषद होती है, जिनमें से अधिकतम चार राज्यपाल द्वारा मनोनीत होते हैं।",
      "राज्यपाल स्वायत्त ज़िलों का गठन और पुनर्गठन कर सकते हैं, जिसमें उनके क्षेत्र को बढ़ाना या घटाना भी शामिल है।",
      "संसद और राज्य विधानमंडल के अधिनियम स्वायत्त ज़िलों पर अपने-आप और बिना किसी संशोधन के लागू होते हैं।",
      "ज़िला परिषदें अनुसूचित जनजातियों के बीच के वादों और मामलों की सुनवाई के लिए ग्राम परिषदें या न्यायालय गठित कर सकती हैं।"])

H("4879d495-566d-4c4b-a155-e3edd6488b1b",
  "संविधान के अनुच्छेदों और उन विषयों के निम्नलिखित युग्मों पर विचार कीजिए जिनके लिए वे विशेष प्रावधान करते हैं:",
  "केवल युग्म 1 और 4 सही हैं: अनुच्छेद 244क (22वाँ संशोधन, 1969) संसद को असम के भीतर एक स्वायत्त राज्य बनाने की अनुमति देता है, और अनुच्छेद 239कक (69वाँ संशोधन, 1991) में दिल्ली के लिए विशेष प्रावधान हैं। "
  "युग्म 2 गलत है: अनुच्छेद 371छ मिज़ोरम से संबंधित है (गोवा अनुच्छेद 371झ में है)। युग्म 3 गलत है: अनुच्छेद 371ज अरुणाचल प्रदेश से संबंधित है (सिक्किम अनुच्छेद 371च में है)।",
  l1=["अनुच्छेद 244क", "अनुच्छेद 371छ", "अनुच्छेद 371ज", "अनुच्छेद 239कक"],
  l2=["असम के भीतर कुछ जनजातीय क्षेत्रों को मिलाकर एक स्वायत्त राज्य", "गोवा", "सिक्किम", "राष्ट्रीय राजधानी क्षेत्र दिल्ली"])

H("e7d748c1-02b9-4cce-b72b-0474178e5ea8",
  "GST परिषद के संबंध में निम्नलिखित कथनों पर विचार कीजिए:",
  "कथन 1 और 2 सही हैं: अनुच्छेद 279क (101वें संशोधन, 2016 द्वारा जोड़ा गया) परिषद बनाता है, और इसके मतदान नियम में केंद्र को भारित मतों का एक-तिहाई और सभी राज्यों को मिलाकर दो-तिहाई मिलता है, तथा निर्णय के लिए तीन-चौथाई बहुमत चाहिए। "
  "कथन 3 निर्णय को उलट देता है: मोहित मिनरल्स (मई 2022) में न्यायालय ने कहा कि परिषद की सिफ़ारिशें बाध्यकारी नहीं हैं, केवल प्रेरक (persuasive) मूल्य रखती हैं, क्योंकि संसद और राज्य विधानमंडलों, दोनों को GST पर एक साथ कानून बनाने की शक्ति है।",
  st=["यह अनुच्छेद 279क के तहत स्थापित एक संवैधानिक निकाय है।",
      "इसके निर्णयों के लिए उपस्थित और मतदान करने वाले सदस्यों के भारित मतों का कम से कम तीन-चौथाई बहुमत चाहिए, जिसमें केंद्र सरकार के मत का भार कुल डाले गए मतों का एक-तिहाई होता है।",
      "भारत संघ बनाम मोहित मिनरल्स (2022) में उच्चतम न्यायालय ने कहा कि GST परिषद की सिफ़ारिशें संसद और राज्य विधानमंडलों पर बाध्यकारी हैं।"])

H("d38bbafc-81a6-472a-8f70-618b0a91a67c",
  "निम्नलिखित कथनों पर विचार कीजिए:",
  "दोनों कथन सही हैं और कथन-II, कथन-I की व्याख्या करता है। अनुच्छेद 254(1) का सामान्य नियम है कि समवर्ती सूची के विषय पर विरोधी (repugnant) राज्य कानून के ऊपर केंद्रीय कानून प्रभावी होता है, पर अनुच्छेद 254(2) इसका अपवाद बनाता है: राष्ट्रपति के विचार के लिए आरक्षित और उनकी स्वीकृति प्राप्त राज्य कानून उस राज्य में प्रभावी होता है। "
  "संसद बाद में उसी विषय पर नया कानून बनाकर इसे फिर भी पलट सकती है।",
  a="समवर्ती सूची के किसी विषय पर राज्य विधानमंडल द्वारा बनाया गया कानून, उस विषय पर संसद के पहले के कानून से विरोधी होने पर भी, उस राज्य में प्रभावी हो सकता है।",
  r="अनुच्छेद 254(2) के तहत ऐसा राज्य कानून उस राज्य में प्रभावी होता है, यदि उसे राष्ट्रपति के विचार के लिए आरक्षित किया गया हो और उसे उनकी स्वीकृति मिल गई हो।")

H("96f5746c-edf6-406a-9521-6f0fe7dcdfe0",
  "अंतरराज्यीय नदी जल विवादों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:",
  "तीनों कथन सही हैं। अनुच्छेद 262(2) संसद को ऐसे विवादों पर उच्चतम न्यायालय सहित सभी न्यायालयों का क्षेत्राधिकार हटाने की अनुमति देता है; अंतरराज्यीय नदी जल विवाद अधिनियम, 1956 के तहत, बातचीत से विवाद न सुलझने पर केंद्र सरकार अधिकरण गठित करती है; और अधिनियम की धारा 6(2) (2002 में जोड़ी गई) अधिकरण के निर्णय को उच्चतम न्यायालय के आदेश या डिक्री के समान बल देती है। "
  "आकर्षक गलती यह मान लेना है कि अधिकरण उच्चतम न्यायालय गठित करता है।",
  st=["अनुच्छेद 262 के तहत संसद कानून बनाकर यह प्रावधान कर सकती है कि ऐसे विवादों पर न तो उच्चतम न्यायालय और न ही कोई अन्य न्यायालय क्षेत्राधिकार का प्रयोग करेगा।",
      "अंतरराज्यीय नदी जल विवाद अधिनियम, 1956 के तहत जल विवाद अधिकरणों का गठन केंद्र सरकार करती है।",
      "अधिनियम के तहत जल विवाद अधिकरण के निर्णय का बल उच्चतम न्यायालय के आदेश या डिक्री के समान होता है।"])

H("783ea318-1efd-4f12-8e38-bf9247b434c6",
  "अनुच्छेद 356 के तहत राष्ट्रपति शासन के संबंध में निम्नलिखित कथनों पर विचार कीजिए:",
  "चारों कथन सही हैं। उद्घोषणा को दो महीने के भीतर संसद की स्वीकृति चाहिए (अनुच्छेद 356(3)); एक वर्ष से आगे जारी रखने के लिए राष्ट्रीय आपातकाल का लागू होना और निर्वाचन आयोग का प्रमाणन, दोनों आवश्यक हैं (44वें संशोधन द्वारा जोड़ा गया अनुच्छेद 356(5)); विधानसभा भंग की जा सकती है या निलंबित अवस्था में रखी जा सकती है; और हर छह महीने की स्वीकृति के साथ यह अधिकतम तीन वर्ष तक चल सकता है।",
  st=["राष्ट्रपति शासन की उद्घोषणा को जारी होने के दो महीने के भीतर संसद के दोनों सदनों की स्वीकृति मिलनी चाहिए।",
      "इसे एक वर्ष से आगे तभी जारी रखा जा सकता है जब राष्ट्रीय आपातकाल लागू हो और निर्वाचन आयोग प्रमाणित करे कि राज्य विधानसभा के चुनाव नहीं कराए जा सकते।",
      "राष्ट्रपति शासन के दौरान राज्य विधानसभा को भंग किया जा सकता है या निलंबित अवस्था (suspended animation) में रखा जा सकता है।",
      "राष्ट्रपति शासन अधिकतम तीन वर्ष तक जारी रखा जा सकता है।"])

H("225fac68-d1a6-4e89-a44c-f058f55e1980",
  "आपातकाल के नागरिकों और वित्त पर प्रभाव के संबंध में निम्नलिखित कथनों पर विचार कीजिए:",
  "कथन 2 और 4 सही हैं: 44वें संशोधन के बाद अनुच्छेद 359 का प्रयोग अनुच्छेद 20 और 21 के प्रवर्तन को निलंबित करने के लिए नहीं हो सकता, और अनुच्छेद 360 का प्रयोग कभी नहीं हुआ। "
  "कथन 1 गलत है: अनुच्छेद 358 (44वें संशोधन द्वारा संशोधित) के तहत अनुच्छेद 19 अपने-आप केवल तभी निलंबित होता है जब आपातकाल युद्ध या बाहरी आक्रमण के आधार पर घोषित हो, सशस्त्र विद्रोह के आधार पर नहीं। "
  "कथन 3 गलत है: वित्तीय आपातकाल को दो महीने के भीतर स्वीकृति चाहिए, और स्वीकृत होने के बाद यह रद्द किए जाने तक अनिश्चित काल तक लागू रहता है।",
  st=["राष्ट्रीय आपातकाल की किसी भी उद्घोषणा पर, सशस्त्र विद्रोह के आधार पर की गई उद्घोषणा सहित, अनुच्छेद 19 अपने-आप निलंबित हो जाता है।",
      "राष्ट्रीय आपातकाल के दौरान राष्ट्रपति अनुच्छेद 20 और 21 द्वारा प्रत्याभूत अधिकारों के प्रवर्तन के लिए न्यायालय जाने के अधिकार को निलंबित नहीं कर सकते।",
      "अनुच्छेद 360 के तहत वित्तीय आपातकाल की उद्घोषणा को जारी होने के एक महीने के भीतर संसद के दोनों सदनों की स्वीकृति मिलनी चाहिए।",
      "भारत में अब तक कोई वित्तीय आपातकाल घोषित नहीं किया गया है।"])

H("0ea56c08-6fe8-4a92-825e-97e880aad15b",
  "अनुच्छेद 352 के तहत राष्ट्रीय आपातकाल की उद्घोषणा के संबंध में निम्नलिखित कथनों पर विचार कीजिए:",
  "कोई भी कथन सही नहीं है। 44वें संशोधन (1978) के बाद राष्ट्रीय आपातकाल की उद्घोषणा को दोनों सदनों की स्वीकृति एक महीने के भीतर चाहिए (दो महीने की अवधि राष्ट्रपति शासन और वित्तीय आपातकाल के लिए है)। "
  "स्वीकृत होने के बाद यह छह महीने तक लागू रहता है और हर छह महीने पर संसद की स्वीकृति से अनिश्चित काल तक बढ़ाया जा सकता है। "
  "इसे जारी रखने के विरोध का प्रस्ताव लोकसभा के केवल साधारण बहुमत से पारित होता है; लोकसभा के दसवें भाग सदस्य इसके लिए विशेष बैठक की माँग कर सकते हैं।",
  st=["इसे जारी होने के दो महीने के भीतर संसद के दोनों सदनों की स्वीकृति मिलनी चाहिए।",
      "संसद की स्वीकृति के बाद यह एक वर्ष तक लागू रहता है और एक-एक वर्ष के लिए बढ़ाया जा सकता है।",
      "आपातकाल जारी रखने के विरोध का प्रस्ताव लोकसभा के विशेष बहुमत से पारित होना चाहिए।"])

H("9c7e60f4-d5e8-44cf-8ea1-5729fdde21ff",
  "मौलिक कर्तव्यों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:",
  "केवल कथन 2 सही है: अनुच्छेद 51क के मौलिक कर्तव्य न्यायालय द्वारा प्रवर्तनीय नहीं हैं, यद्यपि किसी कानून की तर्कसंगतता परखते समय न्यायालय इन्हें ध्यान में रख सकते हैं। "
  "कथन 1 गलत है: इन्हें स्वर्ण सिंह समिति की सिफ़ारिश पर 42वें संशोधन (1976) से जोड़ा गया, और ग्यारहवाँ कर्तव्य 86वें संशोधन (2002) से जुड़ा।",
  st=["मौलिक कर्तव्य 1949 में अपनाए गए मूल संविधान का भाग थे।",
      "मौलिक कर्तव्य न्यायालयों द्वारा प्रवर्तनीय नहीं हैं।"])

H("bfce711a-744c-4c42-868d-3a03b3447ec1",
  "राज्य के नीति निदेशक तत्वों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:",
  "चारों कथन सही हैं। 6-14 वर्ष के बच्चों की प्रारंभिक शिक्षा अनुच्छेद 21क के तहत मौलिक अधिकार बनने के बाद 86वें संशोधन (2002) ने अनुच्छेद 45 को छह वर्ष की आयु तक प्रारंभिक बाल्यावस्था देखरेख और शिक्षा के लिए नए रूप में लिखा; अनुच्छेद 40, 44 और 50 गांधीवादी और उदार-बौद्धिक सिद्धांत हैं जो बिना बदलाव के बने हुए हैं।",
  st=["अनुच्छेद 45 राज्य को निर्देश देता है कि वह सभी बच्चों के लिए छह वर्ष की आयु पूरी होने तक प्रारंभिक बाल्यावस्था देखरेख और शिक्षा की व्यवस्था करे।",
      "अनुच्छेद 40 राज्य को ग्राम पंचायतों का गठन करने का निर्देश देता है।",
      "अनुच्छेद 44 राज्य को निर्देश देता है कि वह भारत के पूरे राज्यक्षेत्र में नागरिकों के लिए एक समान नागरिक संहिता प्राप्त करने का प्रयास करे।",
      "अनुच्छेद 50 राज्य को निर्देश देता है कि वह राज्य की लोक सेवाओं में न्यायपालिका को कार्यपालिका से अलग करने के कदम उठाए।"])

H("b55ffea2-0a28-441b-8334-f09992974652",
  "मौलिक अधिकारों और उन व्यक्तियों के निम्नलिखित युग्मों पर विचार कीजिए जिन्हें वे उपलब्ध हैं:",
  "चारों युग्म सही हैं। अनुच्छेद 15, 16, 19, 29 और 30 केवल नागरिकों को उपलब्ध हैं (अनुच्छेद 29(1) 'नागरिकों के किसी भी अनुभाग' की बात करता है), जबकि अनुच्छेद 14, 20, 21, 21क, 22, 23, 24, 25, 26, 27 और 28 सभी व्यक्तियों को, चाहे नागरिक हों या विदेशी, उपलब्ध हैं; कुछ मामलों में शत्रु विदेशी इसके अपवाद हैं।",
  l1=["अनुच्छेद 15 (भेदभाव का निषेध)", "अनुच्छेद 21 (प्राण और दैहिक स्वतंत्रता का संरक्षण)", "अनुच्छेद 29 (अल्पसंख्यकों के हितों का संरक्षण)", "अनुच्छेद 25 (धर्म की स्वतंत्रता)"],
  l2=["केवल नागरिक", "विदेशियों सहित सभी व्यक्ति", "केवल नागरिक", "विदेशियों सहित सभी व्यक्ति"])

H("447cc827-4034-4c0b-8d70-72ce8e76a9b5",
  "धर्म की स्वतंत्रता के अधिकार के संबंध में निम्नलिखित कथनों पर विचार कीजिए:",
  "कोई भी कथन सही नहीं है। अनुच्छेद 25 सभी व्यक्तियों को, नागरिकों और विदेशियों को समान रूप से, उपलब्ध है। अनुच्छेद 28(1) पूरी तरह राज्य-निधि से चलने वाली शिक्षा संस्थाओं में धार्मिक शिक्षा पर रोक लगाता है। "
  "अनुच्छेद 27 कथन 3 का उलटा कहता है: किसी व्यक्ति को ऐसे कर देने के लिए बाध्य नहीं किया जा सकता जिनकी आय किसी विशेष धर्म के प्रचार या पोषण के लिए निर्धारित हो।",
  st=["अनुच्छेद 25 अंतःकरण की स्वतंत्रता और धर्म को मानने, आचरण करने और प्रचार करने का अधिकार केवल नागरिकों को देता है।",
      "अनुच्छेद 28 पूरी तरह राज्य-निधि से चलने वाली शिक्षा संस्थाओं में धार्मिक शिक्षा की अनुमति देता है।",
      "अनुच्छेद 27 राज्य को किसी व्यक्ति को ऐसे कर देने के लिए बाध्य करने की अनुमति देता है जिनकी आय विशेष रूप से किसी एक धर्म के प्रचार के लिए निर्धारित हो।"])

H("273f425c-c272-43b3-8dea-308506bb93b5",
  "मौलिक अधिकारों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:",
  "केवल कथन 1 सही है: अनुच्छेद 20(3) आत्म-अभिशंसन (self-incrimination) के विरुद्ध संरक्षण है। "
  "कथन 2 गलत है: दोहरे दंड (double jeopardy) से संरक्षण केवल न्यायालय या न्यायिक अधिकरण की कार्यवाही पर लागू होता है, विभागीय या प्रशासनिक कार्यवाही पर नहीं। "
  "कथन 3 गलत है: अनुच्छेद 21क छह से चौदह वर्ष के बच्चों पर लागू है। "
  "कथन 4 गलत है: अनुच्छेद 20(1) केवल भूतलक्षी (ex post facto) आपराधिक कानूनों पर रोक लगाता है; दीवानी या कर संबंधी कानून भूतलक्षी बनाए जा सकते हैं।",
  st=["अनुच्छेद 20(3) के तहत किसी अपराध के आरोपी व्यक्ति को स्वयं अपने विरुद्ध गवाह बनने के लिए बाध्य नहीं किया जाएगा।",
      "अनुच्छेद 20(2) के तहत दोहरे दंड से संरक्षण विभागीय या प्रशासनिक प्राधिकारियों के समक्ष की कार्यवाही पर भी रोक लगाता है।",
      "अनुच्छेद 21क अठारह वर्ष तक की आयु के सभी बच्चों के लिए निःशुल्क और अनिवार्य शिक्षा को मौलिक अधिकार बनाता है।",
      "अनुच्छेद 20(1) भूतलक्षी आपराधिक कानूनों के साथ-साथ भूतलक्षी दीवानी और कर कानूनों पर भी रोक लगाता है।"])

H("e33bdf60-ba98-46e3-8fa7-f6e6fa1ec5be",
  "निम्नलिखित में से कौन-सा नीति निदेशक तत्व 97वें संशोधन अधिनियम, 2011 द्वारा जोड़ा गया?",
  "97वें संशोधन (2011) ने सहकारी समितियों को बढ़ावा देने से संबंधित अनुच्छेद 43ख जोड़ा, साथ ही भाग IXख और अनुच्छेद 19(1)(ग) में 'या सहकारी समितियाँ' शब्द जोड़े। "
  "अनुच्छेद 39क, 43क और 48क सभी इससे पहले 42वें संशोधन (1976) द्वारा जोड़े गए थे।",
  o={"a": "सहकारी समितियों को बढ़ावा देना (अनुच्छेद 43ख)", "b": "समान न्याय और निःशुल्क विधिक सहायता (अनुच्छेद 39क)",
     "c": "उद्योगों के प्रबंधन में कर्मकारों की भागीदारी (अनुच्छेद 43क)", "d": "पर्यावरण का संरक्षण और सुधार (अनुच्छेद 48क)"})

H("cc567df3-7ba1-4841-bd0e-e87ea1a540d7",
  "डॉ. बी.आर. आंबेडकर ने संविधान के किस अनुच्छेद को संविधान का 'हृदय और आत्मा' कहा था?",
  "डॉ. आंबेडकर ने अनुच्छेद 32, यानी मौलिक अधिकारों के प्रवर्तन के लिए उच्चतम न्यायालय जाने के अधिकार, को संविधान की आत्मा और हृदय कहा, क्योंकि उपचार के बिना बाकी अधिकार निरर्थक होते। "
  "उच्चतम न्यायालय ने अनुच्छेद 32 को मूल ढाँचे का भाग माना है।",
  o={"a": "अनुच्छेद 14", "b": "अनुच्छेद 19", "c": "अनुच्छेद 32", "d": "अनुच्छेद 21"})

H("3ee8a5e5-cbf5-49fb-97fe-051b2ca26e30",
  "आर्थिक रूप से कमज़ोर वर्गों (EWS) के लिए आरक्षण के संबंध में निम्नलिखित कथनों पर विचार कीजिए:",
  "कोई भी कथन सही नहीं है। 103वें संशोधन ने अनुच्छेद 15(6) और 16(6) जोड़े; 93वें संशोधन (2005) से जुड़ा अनुच्छेद 15(5) सामाजिक और शैक्षिक रूप से पिछड़े वर्गों, अनुसूचित जातियों और अनुसूचित जनजातियों के लिए शिक्षा संस्थाओं में आरक्षण से संबंधित है। "
  "जनहित अभियान में पाँच न्यायाधीशों की पीठ ने EWS आरक्षण को 3:2 के बहुमत से वैध ठहराया। "
  "EWS कोटा स्पष्ट रूप से उन लोगों को बाहर रखता है जिन्हें पहले से अनुसूचित जाति, अनुसूचित जनजाति या OBC आरक्षण का लाभ मिलता है।",
  st=["103वें संशोधन अधिनियम, 2019 ने आर्थिक रूप से कमज़ोर वर्गों के लिए आरक्षण संभव बनाने हेतु अनुच्छेद 15(5) और 16(5) जोड़े।",
      "जनहित अभियान बनाम भारत संघ (2022) में एक संविधान पीठ ने EWS आरक्षण को 4:1 के बहुमत से वैध ठहराया।",
      "अनुसूचित जाति, अनुसूचित जनजाति और अन्य पिछड़े वर्गों के लोग, आय की शर्त पूरी करने पर, EWS कोटे के पात्र हैं।"])

H("12cbfa77-e490-4ec3-bb58-3e2ef9c07aaf",
  "मौलिक अधिकारों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:",
  "तीनों कथन सही हैं। अनुच्छेद 17 अस्पृश्यता का अंत करता है, और इसका प्रवर्तन सिविल अधिकार संरक्षण अधिनियम, 1955 से होता है। अनुच्छेद 18 राज्य को सैन्य और शैक्षिक विशिष्टताओं के अलावा उपाधियाँ देने से रोकता है। "
  "अनुच्छेद 15(2) उन गिने-चुने मौलिक अधिकारों में है जो निजी व्यक्तियों के विरुद्ध भी लागू होते हैं; आकर्षक गलती यह मान लेना है कि हर मौलिक अधिकार केवल राज्य को बाँधता है।",
  st=["अनुच्छेद 17 'अस्पृश्यता' का अंत करता है और किसी भी रूप में उसके आचरण का निषेध करता है।",
      "अनुच्छेद 18 राज्य को उपाधियाँ देने से रोकता है, पर सैन्य और शैक्षिक विशिष्टताओं को इससे छूट देता है।",
      "अनुच्छेद 15(2) के तहत दुकानों, सार्वजनिक भोजनालयों, होटलों और सार्वजनिक मनोरंजन के स्थानों तक पहुँच में भेदभाव का निषेध राज्य के साथ-साथ निजी व्यक्तियों पर भी लागू होता है।"])

H("a1a16877-af41-400f-924c-604d9dea2acb",
  "निम्नलिखित कथनों पर विचार कीजिए:",
  "दोनों कथन सही हैं, किंतु कथन-II, कथन-I की व्याख्या नहीं करता। कथन-I अनुच्छेद 31ग का वह संरक्षण है जो केशवानंद भारती और मिनर्वा मिल्स के बाद बचा रहा। "
  "कथन-II वह तर्क है जिससे मिनर्वा मिल्स ने 42वें संशोधन द्वारा इस संरक्षण को सभी नीति निदेशक तत्वों तक बढ़ाने को रद्द किया; यह बताता है कि अनुच्छेद 31ग को क्यों सीमित किया गया, यह नहीं कि अनुच्छेद 39(ख)-(ग) का संरक्षण क्यों है।",
  a="अनुच्छेद 39(ख) या (ग) के नीति निदेशक तत्वों को लागू करने वाले कानून को इस आधार पर चुनौती नहीं दी जा सकती कि वह अनुच्छेद 14 या अनुच्छेद 19 का उल्लंघन करता है।",
  r="मिनर्वा मिल्स (1980) में उच्चतम न्यायालय ने कहा कि मौलिक अधिकारों और नीति निदेशक तत्वों के बीच सामंजस्य और संतुलन मूल ढाँचे की एक आवश्यक विशेषता है।")

H("d86037af-9bee-434f-bc0f-d56f18364c08",
  "निम्नलिखित कथनों पर विचार कीजिए:",
  "दोनों कथन सही हैं और कथन-II, कथन-I की व्याख्या करता है: नीति निदेशक तत्वों का न्यायालय द्वारा प्रवर्तनीय न होना सीधे अनुच्छेद 37 के पाठ से निकलता है, जो राज्य का यह कर्तव्य भी बताता है कि वह कानून बनाते समय इन्हें लागू करे।",
  a="राज्य के नीति निदेशक तत्वों को न्यायालयों द्वारा लागू नहीं कराया जा सकता।",
  r="अनुच्छेद 37 स्पष्ट रूप से कहता है कि नीति निदेशक तत्व किसी न्यायालय द्वारा प्रवर्तनीय नहीं होंगे, यद्यपि वे देश के शासन में मूलभूत हैं।")

H("f4518393-2caf-4850-9267-f68061999565",
  "राष्ट्रीय अन्वेषण अभिकरण (NIA) के संबंध में निम्नलिखित कथनों पर विचार कीजिए:",
  "कथन 1 और 2 सही हैं: NIA अधिनियम मुंबई हमलों के बाद दिसंबर 2008 में पारित हुआ, और 2019 के संशोधन ने अभिकरण का क्षेत्राधिकार भारत के बाहर किए गए अनुसूचित अपराधों तक बढ़ाया (साथ ही मानव तस्करी और साइबर-आतंकवाद जैसे अपराध जोड़े)। "
  "कथन 3 गलत है: अधिनियम की धारा 6 के तहत केंद्र सरकार, स्वतः संज्ञान लेकर भी, NIA को भारत में कहीं भी अनुसूचित अपराध की जाँच का निर्देश राज्य की सहमति के बिना दे सकती है; CBI के विपरीत, जिसे DSPE अधिनियम के तहत सामान्यतः राज्य की सहमति चाहिए।",
  st=["NIA का गठन नवंबर 2008 के मुंबई आतंकी हमलों के बाद बने राष्ट्रीय अन्वेषण अभिकरण अधिनियम, 2008 के तहत हुआ।",
      "अधिनियम के 2019 के संशोधन के बाद NIA भारत के बाहर भारतीय नागरिकों के विरुद्ध या भारत के हितों को प्रभावित करने वाले अनुसूचित अपराधों की जाँच कर सकता है।",
      "NIA किसी राज्य में अनुसूचित अपराध की जाँच केवल उस राज्य सरकार की सहमति से ही अपने हाथ में ले सकता है।"])

H("06cf3104-c50b-4b8f-9227-ba40a3075d2b",
  "अखिल भारतीय सेवाओं के संबंध में निम्नलिखित कथनों पर विचार कीजिए:",
  "केवल कथन 1 सही है: यही प्रक्रिया अनुच्छेद 312(1) में दी गई है। "
  "कथन 2 गलत है: अनुच्छेद 312(2) ने संविधान लागू होने के समय केवल IAS और IPS को अखिल भारतीय सेवा माना; भारतीय वन सेवा 1966 में अखिल भारतीय सेवा अधिनियम, 1951 के तहत बनी। "
  "कथन 3 गलत है: इन अधिकारियों पर तात्कालिक नियंत्रण राज्य सरकार का होता है, पर अंतिम नियंत्रण केंद्र का है, और बर्खास्तगी जैसा बड़ा दंड केवल केंद्र सरकार दे सकती है।",
  st=["यदि राज्यसभा उपस्थित और मतदान करने वाले कम से कम दो-तिहाई सदस्यों के समर्थन से यह घोषित करने वाला प्रस्ताव पारित करे कि राष्ट्रीय हित में यह आवश्यक है, तो संसद एक नई अखिल भारतीय सेवा बना सकती है।",
      "भारतीय वन सेवा संविधान लागू होने के समय से ही IAS और IPS के साथ एक अखिल भारतीय सेवा रही है।",
      "चूँकि अखिल भारतीय सेवाओं के सदस्य राज्य सरकारों के अधीन काम करते हैं, इसलिए राज्य सरकार ऐसे अधिकारी को सेवा से बर्खास्त कर सकती है।"])

H("122d0470-e345-463d-bdd2-3f8b389c7c01",
  "निम्नलिखित में से वह ICT-आधारित मंच कौन-सा है जिसके माध्यम से प्रधानमंत्री केंद्रीय सचिवों और राज्यों के मुख्य सचिवों के साथ सीधे बड़ी अवसंरचना परियोजनाओं, सरकारी कार्यक्रमों और जन-शिकायतों की समीक्षा करते हैं?",
  "2015 में शुरू किया गया प्रगति (PRAGATI: Pro-Active Governance and Timely Implementation) बहुउद्देशीय मंच है, जिस पर प्रधानमंत्री केंद्रीय सचिवों और राज्यों के मुख्य सचिवों के साथ समीक्षा बैठकें करते हैं। "
  "CPGRAMS प्रशासनिक सुधार और लोक शिकायत विभाग (DARPG) का शिकायत पोर्टल है, e-SAKSHI MPLADS निधि-प्रवाह का पोर्टल है, और पीएम गति शक्ति बहु-मॉडल अवसंरचना संपर्क की GIS-आधारित योजना है।",
  o={"a": "CPGRAMS", "b": "e-SAKSHI", "c": "पीएम गति शक्ति राष्ट्रीय मास्टर प्लान", "d": "प्रगति (PRAGATI)"})

H("ee4b3dfd-c61f-4512-9de6-40552e49d689",
  "निम्नलिखित में से कौन-सा राज्य भारत में नागरिकों को निर्धारित समय में कुछ विशेष लोक सेवाएँ देने की गारंटी देने वाला कानून बनाने वाला पहला राज्य था?",
  "मध्य प्रदेश ने अगस्त 2010 में मध्य प्रदेश लोक सेवाओं के प्रदान की गारंटी अधिनियम बनाया, जो देश का पहला लोक सेवा अधिकार कानून था; यह समयबद्ध सेवा को कानूनी रूप से बाध्यकारी बनाता है और देरी पर अधिकारियों पर जुर्माना लगाता है। "
  "बिहार ने 2011 में ऐसा कानून बनाया, इसलिए वह आकर्षक गलत विकल्प है।",
  o={"a": "बिहार", "b": "मध्य प्रदेश", "c": "केरल", "d": "पंजाब"})

H("9cad0707-4fe6-4ebe-bcf1-5247bc99832e",
  "केंद्रीय अन्वेषण ब्यूरो (CBI) के संबंध में निम्नलिखित कथनों पर विचार कीजिए:",
  "दोनों कथन सही हैं। जाँच के लिए CBI का कानूनी आधार दिल्ली विशेष पुलिस स्थापना अधिनियम, 1946 है। लोकपाल और लोकायुक्त अधिनियम, 2013 द्वारा DSPE अधिनियम में संशोधन के बाद से निदेशक की नियुक्ति एक समिति की सिफ़ारिश पर होती है, जिसमें प्रधानमंत्री (अध्यक्ष), लोकसभा में विपक्ष के नेता या सबसे बड़े विपक्षी दल के नेता, और भारत के मुख्य न्यायाधीश या उनके द्वारा नामित उच्चतम न्यायालय के न्यायाधीश होते हैं। "
  "पुराने नोट्स पर निर्भर विद्यार्थी कथन 2 को गलत मान सकते हैं: 2014 से पहले यह समिति केंद्रीय सतर्कता आयुक्त की अध्यक्षता में थी।",
  st=["CBI को जाँच की शक्ति दिल्ली विशेष पुलिस स्थापना अधिनियम, 1946 से मिलती है।",
      "CBI के निदेशक की नियुक्ति प्रधानमंत्री की अध्यक्षता वाली एक समिति की सिफ़ारिश पर होती है।"])

H("1d1b8807-1627-4315-bdbe-503cc9ed4314",
  "मंत्रिमंडल सचिवालय के संबंध में निम्नलिखित कथनों पर विचार कीजिए:",
  "तीनों कथन सही हैं। अनुच्छेद 77(3) राष्ट्रपति को सरकार के कामकाज को अधिक सुविधापूर्वक चलाने और मंत्रियों के बीच उसके आवंटन के नियम बनाने का अधिकार देता है; 1961 के कार्य आवंटन नियम और कार्य संचालन नियम, दोनों इसी के तहत बने हैं। "
  "मंत्रिमंडल सचिवालय सीधे प्रधानमंत्री के प्रभार में काम करता है, जिसके प्रशासनिक प्रमुख मंत्रिमंडल सचिव हैं, और मंत्रिमंडल सचिव सिविल सेवा बोर्ड के पदेन अध्यक्ष भी हैं।",
  st=["भारत सरकार (कार्य आवंटन) नियम, 1961 संविधान के अनुच्छेद 77 के तहत राष्ट्रपति बनाते हैं।",
      "मंत्रिमंडल सचिवालय सीधे प्रधानमंत्री के अधीन काम करता है।",
      "मंत्रिमंडल सचिव सिविल सेवा बोर्ड के पदेन अध्यक्ष हैं।"])

